package waffle

import (
	"errors"
	"net/http"
	"strings"
	"testing"
	"time"
)

// Fixed vectors computed independently with
//
//	printf '%s.' "$T"; cat body | openssl dgst -sha256 -hmac "$SECRET"
//
// (legacy: openssl dgst -sha256 -hmac "$SECRET" body). Not generated by
// the code under test.
const (
	whSecret      = "whsec_test_secret"
	whOtherSecret = "whsec_other_secret"
	whT           = int64(1767323045)

	whBody1 = `{"event":"charge.paid","event_id":"d1b0c3a2-0000-4000-8000-000000000001","created_at":"2026-01-02T03:04:05Z","charge_id":"ch_123","status":"paid","amount":100000,"currency":"IDR","mode":"live"}`
	whBody2 = `{"event":"payout.failed","event_id":"d1b0c3a2-0000-4000-8000-000000000002","created_at":"2026-01-02T03:04:05Z","payout_id":"po_9","status":"failed","amount":40000,"currency":"IDR","mode":"sandbox","reason":"Rekening tidak valid — gagal ✓ 日本"}`

	whBody1V2        = "2018c5555c6d3aba3f16464677fe2628fa66e5cf786fcbd31d5078c9d6a864dc"
	whBody1Legacy    = "830202cbcc20bf66c1b459df8ee96d5ef164e4f43390807f446187b5c1511e14"
	whBody2V2        = "87bfb14fd6261671132d2b078f40fc9ea4c67336aa73988b6a1b10019145b168"
	whBody1V2Other   = "7c8fcaa519041e148e2234293fc512a63f9b3b3bbb6dc2105c18663851a49e22"
	whBody1Old300    = "060fac12a9ec992be04a2be745791a02e478477bc2e7cec6ca04b91aba002b1f" // t = whT-300
	whBody1Old301    = "9319089c36da45fc5ac85360df30e02a66d6f6af3b2723b4c7a4a69aac2fed40" // t = whT-301
	whBody1Future300 = "012b80fde0d53dec2fda184843acba55558a03eb2968fad97bd6f891b2ed3ed1" // t = whT+300
	whBody1Future301 = "43548ff997ef4d6f1982da040a5a03923cd7ef02a60b69135d00f3095c12256c" // t = whT+301
)

func whClock() WebhookOption {
	return WithWebhookClock(func() time.Time { return time.Unix(whT, 0) })
}

func whHeaders(kv ...string) http.Header {
	h := http.Header{}
	for i := 0; i < len(kv); i += 2 {
		h[kv[i]] = []string{kv[i+1]} // raw map assignment: no canonicalisation
	}
	return h
}

func wantReason(t *testing.T, err error, want WebhookErrorReason) {
	t.Helper()
	var we *WebhookError
	if !errors.As(err, &we) {
		t.Fatalf("err = %v, want *WebhookError(%s)", err, want)
	}
	if we.Reason != want {
		t.Fatalf("reason = %s (%v), want %s", we.Reason, err, want)
	}
}

func TestVerifyWebhookValidV2(t *testing.T) {
	h := whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody1V2, "X-Waffle-Delivery", "d1b0c3a2-0000-4000-8000-000000000001")
	ev, err := VerifyWebhook([]byte(whBody1), h, whSecret, whClock())
	if err != nil {
		t.Fatal(err)
	}
	if ev.Event != "charge.paid" || ev.EventID != "d1b0c3a2-0000-4000-8000-000000000001" ||
		ev.CreatedAt != "2026-01-02T03:04:05Z" || ev.ChargeID != "ch_123" || ev.PayoutID != "" ||
		ev.Status != "paid" || ev.Amount != 100000 || ev.Currency != "IDR" || ev.Mode != "live" ||
		ev.DeliveryID != "d1b0c3a2-0000-4000-8000-000000000001" {
		t.Fatalf("unexpected event: %+v", ev)
	}
	if ev.Raw["charge_id"] != "ch_123" {
		t.Fatalf("raw map missing fields: %v", ev.Raw)
	}
}

func TestVerifyWebhookUnicodeBody(t *testing.T) {
	h := whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody2V2)
	ev, err := VerifyWebhook([]byte(whBody2), h, whSecret, whClock())
	if err != nil {
		t.Fatal(err)
	}
	if ev.PayoutID != "po_9" || ev.Raw["reason"] != "Rekening tidak valid — gagal ✓ 日本" || ev.Mode != "sandbox" {
		t.Fatalf("unexpected event: %+v", ev)
	}
}

func TestVerifyWebhookFailures(t *testing.T) {
	valid := "t=1767323045,v1=" + whBody1V2
	tests := []struct {
		name    string
		body    string
		secret  string
		headers http.Header
		opts    []WebhookOption
		want    WebhookErrorReason
	}{
		{"tampered body", whBody1 + " ", whSecret, whHeaders("X-Waffle-Signature-V2", valid), nil, WebhookSignatureMismatch},
		{"wrong secret", whBody1, whOtherSecret, whHeaders("X-Waffle-Signature-V2", valid), nil, WebhookSignatureMismatch},
		{"signed with other secret", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody1V2Other), nil, WebhookSignatureMismatch},
		{"timestamp altered", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323046,v1="+whBody1V2), nil, WebhookSignatureMismatch},
		{"stale 301s", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767322744,v1="+whBody1Old301), nil, WebhookTimestampOutOfTolerance},
		{"future 301s", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323346,v1="+whBody1Future301), nil, WebhookTimestampOutOfTolerance},
		{"custom tolerance", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767322744,v1="+whBody1Old301), []WebhookOption{WithWebhookTolerance(60 * time.Second)}, WebhookTimestampOutOfTolerance},
		{"no headers", whBody1, whSecret, http.Header{}, nil, WebhookMissingSignature},
		{"nil headers", whBody1, whSecret, nil, nil, WebhookMissingSignature},
		{"legacy disallowed", whBody1, whSecret, whHeaders("X-Waffle-Signature", "sha256="+whBody1Legacy), []WebhookOption{WithWebhookAllowLegacy(false)}, WebhookMissingSignature},
		{"malformed: no v1", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323045"), nil, WebhookMalformedHeader},
		{"malformed: no t", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "v1="+whBody1V2), nil, WebhookMalformedHeader},
		{"malformed: garbage", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "garbage"), nil, WebhookMalformedHeader},
		{"malformed: empty", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", ""), nil, WebhookMalformedHeader},
		{"malformed: t not numeric", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=abc,v1="+whBody1V2), nil, WebhookMalformedHeader},
		{"malformed: duplicate t", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323045,t=1767323045,v1="+whBody1V2), nil, WebhookMalformedHeader},
		{"malformed: v1 not hex", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1=zzzz"), nil, WebhookMalformedHeader},
		{"malformed: v1 short", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1=abcd"), nil, WebhookMalformedHeader},
		{"malformed legacy prefix", whBody1, whSecret, whHeaders("X-Waffle-Signature", whBody1Legacy), nil, WebhookMalformedHeader},
		{"invalid V2 never falls back to legacy", whBody1, whSecret, whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody1V2Other, "X-Waffle-Signature", "sha256="+whBody1Legacy), nil, WebhookSignatureMismatch},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			ev, err := VerifyWebhook([]byte(tc.body), tc.headers, tc.secret, append([]WebhookOption{whClock()}, tc.opts...)...)
			if ev != nil {
				t.Fatalf("event must be nil on failure, got %+v", ev)
			}
			wantReason(t, err, tc.want)
		})
	}
}

func TestVerifyWebhookToleranceBoundaryInclusive(t *testing.T) {
	for name, hdr := range map[string]string{
		"300s old":    "t=1767322745,v1=" + whBody1Old300,
		"300s future": "t=1767323345,v1=" + whBody1Future300,
	} {
		t.Run(name, func(t *testing.T) {
			if _, err := VerifyWebhook([]byte(whBody1), whHeaders("X-Waffle-Signature-V2", hdr), whSecret, whClock()); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestVerifyWebhookHeaderLeniency(t *testing.T) {
	good := "1767323045"
	tests := map[string]http.Header{
		"lowercase names":      whHeaders("x-waffle-signature-v2", "t=1767323045,v1="+whBody1V2),
		"upper names":          whHeaders("X-WAFFLE-SIGNATURE-V2", "t=1767323045,v1="+whBody1V2),
		"extra whitespace":     whHeaders("X-Waffle-Signature-V2", "  t="+good+" ,  v1="+whBody1V2+"  "),
		"unknown fields":       whHeaders("X-Waffle-Signature-V2", "t=1767323045,v0=deadbeef,v1="+whBody1V2+",v9=x"),
		"multiple v1 (second)": whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody1V2Other+",v1="+whBody1V2),
		"multiple v1 (first)":  whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody1V2+",v1="+whBody1V2Other),
		"v1 hex upper case":    whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1=2018C5555C6D3ABA3F16464677FE2628FA66E5CF786FCBD31D5078C9D6A864DC"),
		"canonical via Set": func() http.Header {
			h := http.Header{}
			h.Set("x-waffle-signature-v2", "t=1767323045,v1="+whBody1V2)
			return h
		}(),
	}
	for name, h := range tests {
		t.Run(name, func(t *testing.T) {
			if _, err := VerifyWebhook([]byte(whBody1), h, whSecret, whClock()); err != nil {
				t.Fatal(err)
			}
		})
	}
}

func TestVerifyWebhookLegacy(t *testing.T) {
	h := whHeaders("x-waffle-signature", "sha256="+whBody1Legacy)

	// Allowed by default; the legacy path has no timestamp check, so any clock passes.
	ev, err := VerifyWebhook([]byte(whBody1), h, whSecret, WithWebhookClock(func() time.Time { return time.Unix(1, 0) }))
	if err != nil || ev.Event != "charge.paid" {
		t.Fatalf("legacy default: ev=%+v err=%v", ev, err)
	}
	_, err = VerifyWebhook([]byte(whBody1), h, whSecret, WithWebhookAllowLegacy(false))
	wantReason(t, err, WebhookMissingSignature)
	_, err = VerifyWebhook([]byte(whBody1+" "), h, whSecret)
	wantReason(t, err, WebhookSignatureMismatch)
	_, err = VerifyWebhook([]byte(whBody1), h, whOtherSecret)
	wantReason(t, err, WebhookSignatureMismatch)
}

func TestVerifyWebhookInvalidJSON(t *testing.T) {
	// Validly signed (computed with openssl) but not a JSON object: "not json", "[1]".
	for _, tc := range []struct{ body, sig string }{
		{"not json", "11cc8c1fd3d46b04aba00e94652bfafdf22a53504b570f4e0e47462e3b05654a"},
		{"[1]", "ce111e366acba8c7e5d2cbf2544eed1850defc0e565adbcc826f94d784506e74"},
	} {
		h := whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+tc.sig)
		_, err := VerifyWebhook([]byte(tc.body), h, whSecret, whClock())
		wantReason(t, err, WebhookInvalidJSON)
	}
}

func TestVerifyWebhookEmptySecret(t *testing.T) {
	if _, err := VerifyWebhook([]byte(whBody1), http.Header{}, ""); err == nil {
		t.Fatal("expected error for empty secret")
	}
}

func TestWebhookErrorOmitsSecret(t *testing.T) {
	_, err := VerifyWebhook([]byte(whBody1), whHeaders("X-Waffle-Signature-V2", "t=1767323045,v1="+whBody1V2Other), whSecret, whClock())
	if err == nil || strings.Contains(err.Error(), whSecret) || strings.Contains(err.Error(), whBody1V2) {
		t.Fatalf("error leaks secret or signature: %v", err)
	}
}
